@page "/notifications"
@rendermode InteractiveServer
@using BlazorNotifications.Services
@inject NotificationService NotificationSvc
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill ms-2">@_notifications.Count</span>
</h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in _notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <div>
                    <strong>#@n.Id</strong> &mdash; @n.Message
                </div>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> _notifications = [];
    private CancellationTokenSource? _cts;

    // Runs during both static SSR *and* interactive render.
    // On the interactive re-render the framework replays parameters but we
    // guard against a double-load with _initialized.
    private bool _initialized;

    protected override void OnInitialized()
    {
        if (!_initialized)
        {
            _notifications = NotificationSvc.GetAll();
            _initialized = true;
        }
    }

    // OnAfterRenderAsync is called only on the *client-interactive* render,
    // never during static SSR — perfect for starting the polling loop.
    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }

        await Task.CompletedTask;
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        // Simulate an external system generating notifications periodically.
        var simulateTimer = 0;

        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);
            }
            catch (TaskCanceledException)
            {
                break;
            }

            // Every ~15 seconds, produce a new fake notification server-side.
            simulateTimer += 5;
            if (simulateTimer >= 15)
            {
                NotificationSvc.SimulateIncoming();
                simulateTimer = 0;
            }

            var lastId = _notifications.Count > 0 ? _notifications.Max(n => n.Id) : 0;
            var newer = NotificationSvc.GetSince(lastId);

            if (newer.Count > 0)
            {
                _notifications.AddRange(newer);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

